{
  "components": {
    "parameters": {
      "AuthorizationHeader": {
        "description": "Bearer ***REDACTED*** access token.",
        "in": "header",
        "name": "Authorization",
        "required": true,
        "schema": {
          "type": "string"
        }
      },
      "IdempotencyKeyHeader": {
        "description": "Required on mutating commerce/command routes; `X-Idempotency-Key` is accepted as an alias.",
        "in": "header",
        "name": "Idempotency-Key",
        "required": true,
        "schema": {
          "type": "string"
        }
      },
      "XCorrelationID": {
        "description": "Optional correlation id (`X-Correlation-Id` accepted); echoed as `X-Correlation-ID` on the response.",
        "in": "header",
        "name": "X-Correlation-ID",
        "required": false,
        "schema": {
          "type": "string"
        }
      },
      "XRequestID": {
        "description": "Optional client-provided request id; echoed on the response when middleware is enabled.",
        "in": "header",
        "name": "X-Request-ID",
        "required": false,
        "schema": {
          "type": "string"
        }
      }
    },
    "schemas": {
      "ConflictErrorResponse": {
        "allOf": [
          {
            "$ref": "#/components/schemas/V1APIErrorEnvelope"
          }
        ],
        "description": "State conflict (HTTP 409) \u2014 illegal transitions, idempotency mismatch, quantity_before_mismatch, etc.",
        "example": {
          "error": {
            "code": "illegal_transition",
            "details": {
              "from": "created",
              "to": "vending"
            },
            "message": "cannot start vend from current order status",
            "requestId": "01ARZ3NDEKTSV4RRFFQ69G5AV"
          }
        }
      },
      "ErrorResponse": {
        "allOf": [
          {
            "$ref": "#/components/schemas/V1APIErrorEnvelope"
          }
        ],
        "description": "Generic handler error using the standard envelope.",
        "example": {
          "error": {
            "code": "invalid_request",
            "details": {},
            "message": "request could not be processed",
            "requestId": "01ARZ3NDEKTSV4RRFFQ69G5AV"
          }
        }
      },
      "ForbiddenErrorResponse": {
        "allOf": [
          {
            "$ref": "#/components/schemas/V1APIErrorEnvelope"
          }
        ],
        "description": "Authenticated but not permitted (HTTP 403).",
        "example": {
          "error": {
            "code": "forbidden",
            "details": {},
            "message": "insufficient role for this route",
            "requestId": "01ARZ3NDEKTSV4RRFFQ69G5AV"
          }
        }
      },
      "InternalErrorResponse": {
        "allOf": [
          {
            "$ref": "#/components/schemas/V1APIErrorEnvelope"
          }
        ],
        "description": "Unexpected server failure (HTTP 500).",
        "example": {
          "error": {
            "code": "internal",
            "details": {},
            "message": "unexpected error",
            "requestId": "01ARZ3NDEKTSV4RRFFQ69G5AV"
          }
        }
      },
      "NotFoundErrorResponse": {
        "allOf": [
          {
            "$ref": "#/components/schemas/V1APIErrorEnvelope"
          }
        ],
        "description": "Unknown resource (HTTP 404).",
        "example": {
          "error": {
            "code": "not_found",
            "details": {
              "resource": "order"
            },
            "message": "order not found",
            "requestId": "01ARZ3NDEKTSV4RRFFQ69G5AV"
          }
        }
      },
      "RateLimitErrorResponse": {
        "allOf": [
          {
            "$ref": "#/components/schemas/V1APIErrorEnvelope"
          }
        ],
        "description": "HTTP 429 when rate limits apply.",
        "example": {
          "error": {
            "code": "rate_limited",
            "details": {
              "retry_after_seconds": 2
            },
            "message": "too many requests",
            "requestId": "01ARZ3NDEKTSV4RRFFQ69G5AV"
          }
        }
      },
      "UnauthorizedErrorResponse": {
        "allOf": [
          {
            "$ref": "#/components/schemas/V1APIErrorEnvelope"
          }
        ],
        "description": "Missing or invalid Bearer ***REDACTED*** (HTTP 401).",
        "example": {
          "error": {
            "code": "unauthenticated",
            "details": {},
            "message": "missing bearer ***REDACTED***",
            "requestId": "01ARZ3NDEKTSV4RRFFQ69G5AV"
          }
        }
      },
      "V1APIErrorEnvelope": {
        "properties": {
          "error": {
            "properties": {
              "code": {
                "type": "string"
              },
              "details": {
                "additionalProperties": true,
                "type": "object"
              },
              "message": {
                "type": "string"
              },
              "requestId": {
                "type": "string"
              }
            },
            "required": [
              "code",
              "message",
              "details",
              "requestId"
            ],
            "type": "object"
          }
        },
        "required": [
          "error"
        ],
        "type": "object"
      },
